import type {LinkContent, LinkDestination} from '@smart/aem-utils';
import {createLinkContent, createMediaUrl} from '@smart/aem-utils';
import type {EnvNameV3} from '@smart/endpoint-directory';
import {FOOTNOTE_CODES} from '@smart/types';
import {
  copyNonNullItems,
  displayMissingDataMessage,
  getItemByKeyAndValue,
} from '@smart/utils';
import type {z} from 'zod';
import type {
  GetProductCatalogueContentFragmentQuery,
  ProductCatalogueTranslationsQuery,
} from '../../graphql';
import {Templates} from '../../types/utility';
import {createId} from '../utils/create-id';
import {collectAndMergeTranslations} from '../utils/translations';

type FeatureAppConfig = {
  readonly id: string;
  readonly featureAppName: string;
  readonly versionHash: string;
  readonly src: string;
  readonly baseUrl: string;
};

export interface BadgeFootnotes {
  [key: string]: string;
}

export interface AppModel {
  readonly pageHeadline?: string;
  readonly subtitleForBasePage: string;
  readonly sidebarTitleMain: string;
  readonly sidebarTitleModel: string;
  readonly sidebarTitleLine: string;
  readonly vehiclesTabLabel: string;
  readonly wallboxesTabLabel: string;
  readonly accessoriesTabLabel: string;
  readonly rangeLabel?: string;
  readonly chargingTimeLabel?: string;
  readonly accelerationLabel?: string;
  readonly brabusVehicleDescriptionText?: string;
  readonly pulseVehicleDescriptionText?: string;
  readonly proVehicleDescriptionText?: string;
  readonly proPlusVehicleDescriptionText?: string;
  readonly launchEditionVehicleDescriptionText?: string;
  readonly premiumVehicleDescriptionText?: string;
  readonly HC11PremiumVehicleDescriptionText?: string;
  readonly HC11ProPlusVehicleDescriptionText?: string;
  readonly HC11BrabusVehicleDescriptionText?: string;
  readonly HC11PulseVehicleDescriptionText?: string;
  readonly HC11ProVehicleDescriptionText?: string;
  readonly Edition25thAnniversaryVehicleDescriptionText?: string;
  readonly HY11BrabusVehicleDescriptionText?: string;
  readonly HY11SummitEditionVehicleDescriptionText?: string;
  readonly HY11PulseVehicleDescriptionText?: string;
  readonly HY11PremiumVehicleDescriptionText?: string;
  readonly HY11ProPlusVehicleDescriptionText?: string;
  readonly HY11ProVehicleDescriptionText?: string;
  readonly vehicleDetailsLinkLabel: string;
  readonly vehicleDetailsLinkPath: string;
  readonly leasingPriceLabel: string;
  readonly leasingPriceLabelSME: string;
  readonly leasingPriceLabelPCP: string;
  readonly cashPriceLabel?: string;
  readonly checkStockCtaLabel?: string;
  readonly checkStockCtaPath?: string;
  readonly customizeCtaLabel?: string;
  readonly customizeCtaPath?: string;
  readonly inclVatLabel: string;
  readonly exclVatLabel: string;
  readonly inclVatLabelForAccessory: string;
  readonly exclVatLabelForAccessory: string;
  readonly emptyStateBodyText: string;
  readonly emptyStateButtonLabel: string;
  readonly emptyStateButtonPath: string;
  readonly wltpDisclaimer: string;
  readonly disclaimerReferences: DisclaimerReferences;
  readonly accessoriesAndWallboxes: AccessoriesAndWallboxes;
  readonly estimatedDeliveryText: string;
  readonly inclVatLabelWithShipping: string;
  readonly exclVatLabelWithShipping: string;
  readonly noCarSelectedNotificationHeadline: string;
  readonly noCarSelectedNotificationText: string;
  readonly energyLabel: string | undefined;
  readonly leasingInformationFeatureAppConfig?: FeatureAppConfig;
  readonly extendedWarrantyAemData: ExtendedWarrantyAemDataTypes;
  readonly premiumConnectivityAemData: premiumConnectivityAemDataTypes;
  readonly translations: Record<string, any>;
  readonly deliveryFootnoteReference: string | undefined;
  readonly badgeFootnotes: BadgeFootnotes;
}

type premiumConnectivityAemDataTypes = {
  tabName: string;
  premiumConnectivityIntroText: string;
  premiumConnectivityHelperText: string;
  missingCarMainHeader: string;
  missingCarPrimarySectionHeader: string;
  missingCarPrimarySectionDescription: string;
  missingCarPrimaryBtnLabel: string;
  missingCarSecondarySectionHeader: string;
  missingCarSecondarySectionDescription: string;
  missingCarSecondaryBtnLabel: string;
  notCashbuyMainHeader: string;
  notCashbuyPrimarySectionHeader: string;
  notCashbuyPrimarySectionDescription: string;
  notCashbuyPrimaryBtnLabel: string;
  notCashbuySecondarySectionHeader: string;
  notCashbuySecondarySectionDescription: string;
  notCashbuySecondaryBtnLabel: string;
  premiumConnectivityProviderPath?: string;
  addonCtaPath?: string;
  newsletterSignupCtaPath?: string;
  title: string;
  leftHeadline: string;
  leftDescription: string;
  leftButtonLabel: string;
  leftButtonPath?: string;
  rightHeadline: string;
  rightDescription: string;
  rightButtonLabel: string;
  rightButtonPath?: string;
};

type ExtendedWarrantyAemDataTypes = {
  tabName: string;
  extendedWarrantyIntroText: string;
  extendedWarrantyHelperText: string;
  missingCarMainHeader: string;
  missingCarPrimarySectionHeader: string;
  missingCarPrimarySectionDescription: string;
  missingCarPrimaryBtnLabel: string;
  missingCarSecondarySectionHeader: string;
  missingCarSecondarySectionDescription: string;
  missingCarSecondaryBtnLabel: string;
  notCashbuyMainHeader: string;
  notCashbuyPrimarySectionHeader: string;
  notCashbuyPrimarySectionDescription: string;
  notCashbuyPrimaryBtnLabel: string;
  notCashbuySecondarySectionHeader: string;
  notCashbuySecondarySectionDescription: string;
  notCashbuySecondaryBtnLabel: string;
  extendedWarrantyProviderPath?: string;
  addonCtaPath?: string;
  newsletterSignupCtaPath?: string;
  title: string;
  leftHeadline: string;
  leftDescription: string;
  leftButtonLabel: string;
  leftButtonPath?: LinkContent;
  rightHeadline: string;
  rightDescription: string;
  rightButtonLabel: string;
  rightButtonPath?: string;
};

// TODO: Update name to reflect that this comes from AEM
type AccessoriesAndWallboxes = {
  readonly accessoriesHelperRichText: string;
  readonly accessoriesIntroText: string;
  readonly accessoriesModalDealerLocatorDetails: string;
  readonly accessoriesModalDealerLocatorHeadline: string;
  readonly accessoriesModalSelectCarDetails: string;
  readonly accessoriesModalSelectCarHeadline: string;
  readonly accessoriesModalInfoText: string;
  readonly loginCtaLabel: string;
  readonly loginCtaPath: string;
  readonly selectACarCtaLabel: string;
  readonly selectACarCtaPath: LinkContent | undefined;
  readonly shoppingCartCtaLabel: string;
  readonly shoppingCartCtaPath: string;
  readonly wallboxesWithPedestalFilter: string;
  readonly wallboxesWithInstallationServiceFilter: string;
  readonly wallboxesWithIntegratedCableFilter: string;
  readonly wallboxesModalInfoText: string;
  readonly wallboxesModalLoginDetails: string;
  readonly wallboxesModalLoginHeadline: string;
  readonly wallboxesModalSelectCarHeadline: string;
  readonly wallboxesModelSelectCarDetails: string;
  readonly wallboxesTabHelperText: string;
  readonly wallboxesTabIntroText: string;
  readonly moreDetailsLinkLabel: string;
  readonly moreDetailsLinkPath: string;
  readonly priceLabel: string;
  readonly addItemCtaLabel: string;
  readonly addItemCtaPath: string;
  readonly soldByLabel: string;
  readonly itemAddedCtaLabel: string;
  readonly accessoriesIncompatibleCarModalChangeLineCtaLabel: string; // mapped to sharedModalIncompatibleCarCtaLabel from AEM
  readonly accessoriesIncompatibleCarModalChangeLineCtaPath: string; // mapped to sharedModalIncompatibleCarCtaPath from AEM
  readonly accessoriesIncompatibleCarModalChangeLineHeadline: string; // mapped to sharedModalIncompatibleCarHeadline from AEM
  readonly accessoriesIncompatibleCarModalChangeLineDetails: string; // mapped to sharedModalIncompatibleCarDetails from AEM
  readonly outOfStockModalHeadline: string;
  readonly outOfStockModalDetails: string;
  readonly accessoriesIncompatibleCarModalInfoText: string;
  readonly accessoriesIncompatibleCarModalKeepCurrentHeadline: string;
  readonly accessoriesIncompatibleCarModalKeepCurrentDetails: string;
  readonly headlineForReplaceWallboxNotification: string;
  readonly textForReplaceWallboxNotification: string;
  readonly dealerLocatorCtaLabel: string;
  readonly compatibleWithLabel: string;
};

// TODO: Update name to reflect that this comes from AEM
type DisclaimerReferences = {
  readonly vehicleRangeDisclaimerReference: string;
  readonly vehicleChargingTimeDisclaimerReference: string;
  readonly vehicleAccelerationDisclaimerReference: string;
  readonly vehicleLeasePriceDisclaimerReference: string;
  readonly vehicleCashPriceDisclaimerReference: string;
  readonly wallboxPriceDisclaimerReference: string;
  readonly accessoriesPriceDisclaimerReference: string;
  readonly extendedWarrantyPriceDisclaimerReference: string;
};

const COMMON_ATTRIBUTE_LABEL = {
  LEASING_PRICE_PRIVATE: `leasingPrice`,
  LEASING_PRICE_COMMERCIAL: `leasingPriceSME`,
  ACCESSORY_EXCL_VAT_LABEL: `accessoryExclVatLabel`,
  ACCESSORY_INCL_VAT_LABEL: `accessoryInclVatLabel`,
} as const;

// eslint-disable-next-line complexity
export function createAppModel(
  contentFragment: GetProductCatalogueContentFragmentQuery,
  translationsQuery: ProductCatalogueTranslationsQuery | undefined,
  envName: EnvNameV3,
  preview: boolean,
): AppModel {
  const {
    pageHeadline,
    vehiclesTabLabel,
    wallboxesTabLabel,
    accessoriesTabLabel,
    rangeLabel,
    chargingTimeLabel,
    accelerationLabel,
    pulseVehicleDescriptionText,
    brabusVehicleDescriptionText,
    premiumVehicleDescriptionText,
    proVehicleDescriptionText,
    proPlusVehicleDescriptionText,
    launchEditionVehicleDescriptionText,
    fragmentReferenceToV2Content,
    vehicleDetailsLinkLabel,
    vehicleDetailsLinkPath,
    pcpLeasePriceLabel,
    cashPriceLabel,
    checkStockCtaLabel,
    checkStockCtaPath,
    customizeCtaLabel,
    customizeCtaPath,
    inclVatLabel,
    exclVatLabel,
    emptyStateBodyText,
    emptyStateButtonLabel,
    emptyStateButtonPath,
    wltpDisclaimer,
    disclaimerReference,
    accessoriesAndWallboxesContentFragment,
    estimatedDeliveryText,
    inclVatLabelWithShipping,
    exclVatLabelWithShipping,
    noCarSelectedNotificationHeadline,
    noCarSelectedNotificationText,
    energyLabel,
    fragmentReferenceForProductCatalogueExtendedWarranty,
  } = contentFragment.productCatalogueFeatureAppContentByPath.item;

  const commonLabels = copyNonNullItems(
    contentFragment.commonAttributesByPath.item.labels ?? [],
  );

  const missingText = getMissingText(envName);

  const {
    label: leasingPriceLabel,
    labelSuperscript: vehicleLeasePriceDisclaimerReference,
  } =
    getItemByKeyAndValue(
      commonLabels,
      `key`,
      COMMON_ATTRIBUTE_LABEL.LEASING_PRICE_PRIVATE,
    ) || {};

  const {label: exclVatLabelForAccessory} =
    getItemByKeyAndValue(
      commonLabels,
      `key`,
      COMMON_ATTRIBUTE_LABEL.ACCESSORY_EXCL_VAT_LABEL,
    ) || {};

  const {label: inclVatLabelForAccessory} =
    getItemByKeyAndValue(
      commonLabels,
      `key`,
      COMMON_ATTRIBUTE_LABEL.ACCESSORY_INCL_VAT_LABEL,
    ) || {};

  const imageUrl = energyLabel
    ? createMediaUrl(`image`, energyLabel, {
        envName,
        preview,
      })
    : undefined;

  const leasingInformationFeatureAppVersion =
    contentFragment.productCatalogueFeatureAppContentByPath.item
      .leasingInformationFeatureAppConfig?.version;

  const {
    subtitleForBasePage,
    sidebarTitleMain,
    sidebarTitleModel,
    sidebarTitleLine,
    HC11PremiumVehicleDescriptionText,
    HC11ProPlusVehicleDescriptionText,
    HC11BrabusVehicleDescriptionText,
    HC11PulseVehicleDescriptionText,
    HC11ProVehicleDescriptionText,
    Edition25thAnniversaryVehicleDescriptionText,
    HY11BrabusVehicleDescriptionText,
    HY11SummitEditionVehicleDescriptionText,
    HY11PulseVehicleDescriptionText,
    HY11PremiumVehicleDescriptionText,
    HY11ProPlusVehicleDescriptionText,
    HY11ProVehicleDescriptionText,
    fragmentReferenceForProductCataloguePremiumConnectivity,
  } = fragmentReferenceToV2Content || {};

  const translationsItem = translationsQuery?.featureAppTranslationsByPath.item;

  const commonFootnotes = contentFragment.commonFootnotesByPath;

  const commonSalesToolsFootnotes = commonFootnotes?.item?.salesToolsFootnotes;

  const deliveryFootnoteReference =
    commonSalesToolsFootnotes?.[FOOTNOTE_CODES.DELIVERY_TIME];

  return {
    noCarSelectedNotificationHeadline: noCarSelectedNotificationHeadline || ``,
    noCarSelectedNotificationText: noCarSelectedNotificationText || ``,
    estimatedDeliveryText: estimatedDeliveryText || Templates.days,
    pageHeadline: pageHeadline || ``,
    subtitleForBasePage: subtitleForBasePage || ``,
    sidebarTitleMain: sidebarTitleMain || ``,
    sidebarTitleModel: sidebarTitleModel || ``,
    sidebarTitleLine: sidebarTitleLine || ``,
    vehiclesTabLabel: vehiclesTabLabel || ``,
    wallboxesTabLabel: wallboxesTabLabel || ``,
    accessoriesTabLabel: accessoriesTabLabel || ``,
    rangeLabel: rangeLabel || ``,
    chargingTimeLabel: chargingTimeLabel || ``,
    accelerationLabel: accelerationLabel || ``,
    energyLabel: imageUrl,
    pulseVehicleDescriptionText: pulseVehicleDescriptionText?.plaintext || ``,
    brabusVehicleDescriptionText: brabusVehicleDescriptionText?.plaintext || ``,
    premiumVehicleDescriptionText:
      premiumVehicleDescriptionText?.plaintext || ``,
    proVehicleDescriptionText: proVehicleDescriptionText?.plaintext || ``,
    proPlusVehicleDescriptionText:
      proPlusVehicleDescriptionText?.plaintext || ``,
    launchEditionVehicleDescriptionText:
      launchEditionVehicleDescriptionText?.plaintext || ``,
    HC11PremiumVehicleDescriptionText:
      HC11PremiumVehicleDescriptionText?.plaintext || ``,
    HC11ProPlusVehicleDescriptionText:
      HC11ProPlusVehicleDescriptionText?.plaintext || ``,
    HC11BrabusVehicleDescriptionText:
      HC11BrabusVehicleDescriptionText?.plaintext || ``,
    HC11PulseVehicleDescriptionText:
      HC11PulseVehicleDescriptionText?.plaintext || ``,
    HC11ProVehicleDescriptionText:
      HC11ProVehicleDescriptionText?.plaintext || ``,
    Edition25thAnniversaryVehicleDescriptionText:
      Edition25thAnniversaryVehicleDescriptionText?.plaintext || ``,
    HY11BrabusVehicleDescriptionText:
      HY11BrabusVehicleDescriptionText?.plaintext || ``,
    HY11SummitEditionVehicleDescriptionText:
      HY11SummitEditionVehicleDescriptionText?.plaintext || ``,
    HY11PulseVehicleDescriptionText:
      HY11PulseVehicleDescriptionText?.plaintext || ``,
    HY11PremiumVehicleDescriptionText:
      HY11PremiumVehicleDescriptionText?.plaintext || ``,
    HY11ProPlusVehicleDescriptionText:
      HY11ProPlusVehicleDescriptionText?.plaintext || ``,
    HY11ProVehicleDescriptionText:
      HY11ProVehicleDescriptionText?.plaintext || ``,
    vehicleDetailsLinkLabel: vehicleDetailsLinkLabel || ``,
    vehicleDetailsLinkPath: vehicleDetailsLinkPath?._path || ``,
    leasingPriceLabel: leasingPriceLabel || missingText(`common.leasingPrice`),
    leasingPriceLabelSME:
      getItemByKeyAndValue(
        commonLabels,
        `key`,
        COMMON_ATTRIBUTE_LABEL.LEASING_PRICE_COMMERCIAL,
      )?.label || missingText(`common.leasingPriceSME`),
    leasingPriceLabelPCP:
      pcpLeasePriceLabel || missingText(`pcpLeasePriceLabel`),
    cashPriceLabel: cashPriceLabel || ``,
    checkStockCtaLabel: checkStockCtaLabel || ``,
    checkStockCtaPath: checkStockCtaPath?._path || ``,
    customizeCtaLabel: customizeCtaLabel || ``,
    customizeCtaPath: customizeCtaPath?._path || ``,
    inclVatLabel: inclVatLabel || ``,
    exclVatLabel: exclVatLabel || ``,
    inclVatLabelForAccessory: inclVatLabelForAccessory || ``,
    exclVatLabelForAccessory: exclVatLabelForAccessory || ``,
    emptyStateBodyText: emptyStateBodyText || ``,
    emptyStateButtonLabel: emptyStateButtonLabel || ``,
    emptyStateButtonPath: emptyStateButtonPath?._path || ``,
    wltpDisclaimer: wltpDisclaimer?.plaintext || ``,
    inclVatLabelWithShipping: inclVatLabelWithShipping || ``,
    exclVatLabelWithShipping: exclVatLabelWithShipping || ``,
    leasingInformationFeatureAppConfig: leasingInformationFeatureAppVersion
      ? {
          id: createId(leasingInformationFeatureAppVersion),
          featureAppName:
            leasingInformationFeatureAppVersion.featureAppName || ``,
          versionHash: leasingInformationFeatureAppVersion.versionHash || ``,
          src: leasingInformationFeatureAppVersion.src || ``,
          baseUrl: `/__app__/${leasingInformationFeatureAppVersion.featureAppName}/${leasingInformationFeatureAppVersion.versionHash}`,
        }
      : undefined,

    accessoriesAndWallboxes: {
      accessoriesHelperRichText:
        accessoriesAndWallboxesContentFragment?.accessoriesHelperRichText
          ?.markdown || ``,
      accessoriesIntroText:
        accessoriesAndWallboxesContentFragment?.accessoriesIntroText
          ?.markdown || ``,
      accessoriesModalDealerLocatorDetails:
        accessoriesAndWallboxesContentFragment
          ?.accessoriesModalDealerLocatorDetails?.plaintext || ``,
      accessoriesModalDealerLocatorHeadline:
        accessoriesAndWallboxesContentFragment?.accessoriesModalDealerLocatorHeadline ||
        ``,
      accessoriesModalSelectCarHeadline:
        accessoriesAndWallboxesContentFragment?.accessoriesModalSelectCarHeadline ||
        ``,
      accessoriesModalSelectCarDetails:
        accessoriesAndWallboxesContentFragment?.accessoriesModalSelectCarDetails
          ?.plaintext || ``,
      accessoriesModalInfoText:
        accessoriesAndWallboxesContentFragment?.accessoriesModalInfoText
          ?.plaintext || ``,
      loginCtaLabel:
        accessoriesAndWallboxesContentFragment?.loginCtaLabel || ``,
      loginCtaPath:
        accessoriesAndWallboxesContentFragment?.loginCtaPath?._path || ``,
      selectACarCtaLabel:
        accessoriesAndWallboxesContentFragment?.selectACarCtaLabel || ``,
      selectACarCtaPath:
        accessoriesAndWallboxesContentFragment?.selectACarCtaPath
          ? createLinkContent({
              destination:
                accessoriesAndWallboxesContentFragment?.selectACarCtaPath as z.TypeOf<
                  typeof LinkDestination
                >,
              label:
                accessoriesAndWallboxesContentFragment?.selectACarCtaLabel ||
                ``,
            })
          : undefined,
      shoppingCartCtaLabel:
        accessoriesAndWallboxesContentFragment?.shoppingCartCtaLabel || ``,
      shoppingCartCtaPath:
        accessoriesAndWallboxesContentFragment?.shoppingCartCtaPath?._path ||
        ``,
      wallboxesWithPedestalFilter:
        accessoriesAndWallboxesContentFragment?.wallboxesWithPedestalFilter ||
        ``,
      wallboxesWithInstallationServiceFilter:
        accessoriesAndWallboxesContentFragment?.wallboxesWithInstallationServiceFilter ||
        ``,
      wallboxesWithIntegratedCableFilter:
        accessoriesAndWallboxesContentFragment?.wallboxesWithIntegratedCableFilter ||
        ``,
      wallboxesModalInfoText:
        accessoriesAndWallboxesContentFragment?.wallboxesModalInfoText
          ?.plaintext || ``,
      wallboxesModalLoginDetails:
        accessoriesAndWallboxesContentFragment?.wallboxesModalLoginDetails
          ?.plaintext || ``,
      wallboxesModalLoginHeadline:
        accessoriesAndWallboxesContentFragment?.wallboxesModalLoginHeadline ||
        ``,
      wallboxesModalSelectCarHeadline:
        accessoriesAndWallboxesContentFragment?.wallboxesModalSelectCarHeadline ||
        ``,
      wallboxesModelSelectCarDetails:
        accessoriesAndWallboxesContentFragment?.wallboxesModelSelectCarDetails
          ?.plaintext || ``,
      wallboxesTabHelperText:
        accessoriesAndWallboxesContentFragment?.wallboxesTabHelperText
          ?.markdown || ``,
      wallboxesTabIntroText:
        accessoriesAndWallboxesContentFragment?.wallboxesTabIntroText
          ?.markdown || ``,
      moreDetailsLinkLabel:
        accessoriesAndWallboxesContentFragment?.moreDetailsLinkLabel || ``,
      moreDetailsLinkPath:
        accessoriesAndWallboxesContentFragment?.moreDetailsLinkPath?._path ||
        ``,
      addItemCtaLabel:
        accessoriesAndWallboxesContentFragment?.addItemCtaLabel || ``,
      addItemCtaPath:
        accessoriesAndWallboxesContentFragment?.addItemCtaPath?._path || ``,
      priceLabel: accessoriesAndWallboxesContentFragment?.priceLabel || ``,
      soldByLabel: accessoriesAndWallboxesContentFragment?.soldByLabel || ``,
      itemAddedCtaLabel:
        accessoriesAndWallboxesContentFragment?.itemAddedCtaLabel || ``,
      accessoriesIncompatibleCarModalChangeLineHeadline:
        accessoriesAndWallboxesContentFragment?.sharedModalIncompatibleCarHeadline ||
        ``,
      accessoriesIncompatibleCarModalChangeLineDetails:
