import {createMediaUrl} from '@smart/aem-utils';
import type {CreateMediaUrlOptions} from '@smart/aem-utils';
import type {ModelCode, ProductType} from '@smart/types';
import {displayMissingDataMessage} from '@smart/utils';
import type {LineName} from '../../types/utility';
import type {
  Badge,
  BundleProduct,
  CategoryData,
  Classification,
  CompatibleLines,
  CompatibleProduct,
  CompatibleProductsApiResponse,
  Feature,
  FetchAllModelLinesApiResponse,
  LineOverviewApiResponse,
  Model,
  Product,
} from '../types';

export type ProductCatalogueModel = {
  models: Model[];
  allLines: {[key in ModelCode]: Line[]};
  accessories: ProductSearchProduct[];
  extendedWarranty: ProductSearchProduct[];
  premiumConnectivity: ProductSearchProduct[];
  wallbox: ProductSearchProduct[];
};

export type Line = {
  lineName: LineName | '';
  modelName: string;
  modelCode: ModelCode | '';
  modelYear: string;
  imageUrl: string;
  range: Highlight;
  chargingTime: Highlight;
  acceleration: Highlight;
  colors: Color[];
  defaultPn18: string;
  price: string;
  priceRaw: number;
  leasingPrice: string;
  netPrice: string;
  netLeasingPrice: string;
  isInStock: boolean;
  lineCode: string;
  classifications: Classification[];
  stockLevelStatus: string;
  roofCode: string;
  priority: number;
  badges?: Badge[];
};

type Color = {
  imageUrl: string;
  name: string;
  colorCode: string;
  roofCode: string;
};

type Highlight = {
  label?: string;
  value?: string;
};

export type ProductSearchProduct = {
  productId: string;
  imageUrl: string;
  headline: string;
  description?: string;
  price: string;
  priceRaw: number;
  netPrice: string;
  brand: string;
  soldBy?: string;
  alreadyInCart: boolean;
  isInStock: boolean;
  incompatibleWithCart?: boolean;
  isCategoryPedestal?: boolean;
  isCategoryInstallation?: boolean;
  isCategoryCable?: boolean;
  isCategoryWallboxOnly?: boolean;
  earliestBeautifiedLeadTime?: string;
  stockLevelStatus: string;
  compatibleLines: CompatibleLines[];
  productType: ProductType;
  badges?: Badge[];
};

const getHighlight = (
  productModel: Product,
  featureCode: string,
): Highlight => {
  const feature = productModel.classifications
    ?.flatMap((element) => {
      return element.features;
    })
    .find((f) => f?.code === featureCode);

  return {
    label: feature?.name,
    value: feature?.featureValues?.[0]?.value,
  };
};

const transformColors = (
  colors: CategoryData[],
  options: CreateMediaUrlOptions,
): Color[] => {
  return colors?.map(({code, name, roofCode}) => {
    const imageUrl = createMediaUrl(
      `image`,
      `SMART_COMMON_CS_EXT_${code}-${roofCode}?wid=100`,
      options,
    );
    return {
      name,
      imageUrl,
      colorCode: code,
      roofCode,
    };
  });
};

const transformVehicleProduct = (
  product: Product,
  options: CreateMediaUrlOptions,
): Line => {
  const productionData = (product.classifications || []).find(
    (classification) => classification.code === `PRODUCTIONDATA`,
  );
  const modelYearDescription = productionData?.features?.find(
    (feature: Feature) =>
      feature.code ===
      `smartClassificationCatalog/1.0/PRODUCTIONDATA.modelyeardescription`,
  );
  const modelName = product.name.substring(0, 8);
  const colors = transformColors(product.exterior, options);
  const modelYear = modelYearDescription?.featureValues?.[0]?.value;
  const imageUrl = createMediaUrl(`image`, `ppo_${product.code}`, options);
  const lineCategory = product.categories.find(
    (category) => category.categoryType === `LINE`,
  );
  const lineName = (lineCategory?.name || ``) as LineName;
  const lineCode = lineCategory?.code || ``;

  const isInStock = product.stock.stockLevelStatus === `inStock`;
  const modelCategory = product.categories.find(
    (category) => category.categoryType === `MODEL`,
  );
  const modelCode = (modelCategory?.code || ``) as ModelCode | '';

  const priority = lineCategory?.priority || 1000; // if line has no priority it will be last in the order

  if (!lineName) console.error(`lineName should not be empty:`, product);
  if (!modelCode) console.error(`modelCode should not be empty`, product);

  return {
    lineName,
    acceleration: getHighlight(
      product,
      `smartClassificationCatalog/1.0/POWER.acceleration`,
    ),
    chargingTime: getHighlight(
      product,
      `smartClassificationCatalog/1.0/CONSUMPTION.dcchargingtime`,
    ),
    colors,
    defaultPn18: product.code,
    imageUrl,
    modelName,
    modelYear: modelYear || ``,
    modelCode,
    lineCode,
    classifications: product.classifications,
    range: getHighlight(
      product,
      `smartClassificationCatalog/1.0/CONSUMPTION.range_wltp_combined`,
    ),
    isInStock,
    stockLevelStatus: product.stock.stockLevelStatus,
    price: product.price?.formattedValue ?? `-`,
    priceRaw: product.price?.value ?? `-`,
    leasingPrice: product.leasingPrice?.formattedValue ?? `-`,
    netPrice: product.netPrice?.formattedValue ?? `-`,
    netLeasingPrice: product.netLeasingPrice?.formattedValue ?? `-`,
    roofCode: product.roofCode,
    priority,
    badges: product.badges ?? [],
  };
};

const hasCategory = (product: BundleProduct, categoryCode: string) =>
  !!product?.categories?.find((category) => category.code === categoryCode);

const transformBundleProduct = (
  product: CompatibleProduct,
  options: CreateMediaUrlOptions,
  imagePrefix: string,
): ProductSearchProduct => {
  const {
    code,
    brand,
    soldBy,
    name,
    price,
    netPrice,
    description,
    stock,
    productType,
    badges,
  } = product.product;

  const imageUrl = createMediaUrl(`image`, `${imagePrefix}${code}`, options);

  const isInStock = stock.stockLevelStatus === `inStock`;

  return {
    productId: code,
    imageUrl,
    headline: name,
    description,
    price: price?.formattedValue,
    priceRaw: price?.value,
    isInStock,
    netPrice: netPrice?.formattedValue,
    brand,
    soldBy:
      soldBy ||
      displayMissingDataMessage({
        dataSource: `API`,
        envName: options.envName,
        labelName: `soldBy`,
        preview: options.preview,
      }),
    stockLevelStatus: stock.stockLevelStatus,
    alreadyInCart: product.alreadyInCart,
    isCategoryPedestal: hasCategory(product.product, `ABB-Pedestal`),
    isCategoryInstallation: hasCategory(
      product.product,
      `ABB-StandardInstallation`,
    ),
    isCategoryCable: hasCategory(product.product, `ABB-Cable`),
    earliestBeautifiedLeadTime: stock.earliestBeautifiedLeadTime,
    compatibleLines: product.compatibleLines,
    productType,
    badges: badges || [],
  };
};

export function createProductCatalogueModel(
  allModels: FetchAllModelLinesApiResponse[`data`],
  allLineOverviewData: LineOverviewApiResponse[`data`],
  accessoryResponse: CompatibleProductsApiResponse,
  extendedWarrantyResponse: CompatibleProductsApiResponse,
  wallboxResponse: CompatibleProductsApiResponse,
  premiumConnectivityResponse: CompatibleProductsApiResponse,
  options: CreateMediaUrlOptions,
): ProductCatalogueModel {
  const models = allModels.map(({name, code}) => ({
    code,
    name,
  }));
  const accessories =
    accessoryResponse?.products?.map((product) =>
      transformBundleProduct(product, options, `ADDON_`),
    ) || [];

  const extendedWarranty =
    extendedWarrantyResponse?.products?.map((product) =>
      transformBundleProduct(product, options, ``),
    ) || [];
  const wallbox =
    wallboxResponse?.products?.map((product) =>
      transformBundleProduct(product, options, ``),
    ) || [];

  const premiumConnectivity =
    premiumConnectivityResponse?.products?.map((product) =>
      transformBundleProduct(product, options, ``),
    ) || [];

  const transformedAllLineProducts = allLineOverviewData
    .map((item) => {
      return transformVehicleProduct(item.product, options);
    })
    .reverse();
  const categorizedData = transformedAllLineProducts.reduce(
    (acc, curr) => {
      const modelCode = curr.modelCode;
      if (modelCode) {
        acc[modelCode]?.push(curr);
        acc[modelCode]?.sort((a, b) => a.priority - b.priority);
      }
      return acc;
    },
    {HX11: [], HC11: [], HY11: []} as {[key in ModelCode]: Line[]},
  );

  const filteredCategorizedData = Object.fromEntries(
    Object.entries(categorizedData).filter(([_, lines]) => lines.length > 0),
  ) as {[key in ModelCode]: Line[]};

  return {
    models,
    allLines: filteredCategorizedData,
    accessories,
    extendedWarranty,
    premiumConnectivity,
    wallbox,
  };
}

import {bff} from '@smart/feature-app/node';
import {
  PRODUCT_TYPE,
  salesChannelSchema,
  stringToBooleanSchema,
} from '@smart/types';
import {Config} from 'sst/node/config';
import {z} from 'zod';
import {fetchCart} from '../cart-model/fetch-cart';
import {logger} from '../utils/logger';
import {createProductCatalogueModel} from './create-product-catalogue-model';
import {fetchCartCompatibleProducts} from './fetch-cart-compatible-products';
import {fetchCompatibleProducts} from './fetch-compatible-products';
import {fetchLineOverview} from './fetch-line-overview';
import {fetchSmartModels} from './fetch-smart-models';

export const queryParamsSchema = z.object({
  salesChannel: salesChannelSchema,
  enableAnonymousFlow: stringToBooleanSchema.optional(),
});

export const handler = bff(
  async ({
    user,
    endpoints,
    language,
    envName,
    preview,
    adb,
    baseSiteId,
    cart,
    queryParams: {salesChannel, enableAnonymousFlow},
    featureFlags,
  }) => {
    const cartId = enableAnonymousFlow
      ? cart?.guid || cart?.code || `current`
      : `current`;
    const userId = user ? user.userId : `anonymous`;

    const compatibleProductsOptions = {
      baseSiteId,
      endpoints,
      language,
      userId,
      ecomAccessToken: user?.ecomAccessToken,
      customerId: adb?.customerUserId,
      salesChannel,
    };

    let wallboxCompatibleProductsRequest,
      accessoriesCompatibleProductsRequest,
      extendedWarrantyCompatibilityRequest,
      premiumConnectivityCompatibilityRequest;

    try {
      if (userId !== `anonymous` || cartId !== `current`) {
        const cartResponse = await fetchCart({
          accessToken: user?.accessToken,
          baseSiteId,
          ecomAccessToken: user?.ecomAccessToken,
          endpoints,
          idToken: user?.idToken,
          language,
          userId,
          cartId,
          customerId: adb?.customerUserId,
          salesChannel,
        });

        const entryGroupNumber = cartResponse.entries
          ?.find((entry) => entry.product.productType === PRODUCT_TYPE.VEHICLE)
          ?.entryGroupNumber.toString();
        const compatibleCartProductRequestOptions = {
          accessToken: user?.accessToken,
          baseSiteId,
          customerId: adb?.customerUserId,
          ecomAccessToken: user?.ecomAccessToken,
          endpoints,
          entryGroupNumber: entryGroupNumber || `0`,
          idToken: user?.idToken,
          language,
          salesChannel,
          userId,
          cartId,
        };

        accessoriesCompatibleProductsRequest = fetchCartCompatibleProducts({
          ...compatibleCartProductRequestOptions,
          bundleComponent: `accessories`,
        });
        wallboxCompatibleProductsRequest = fetchCompatibleProducts({
          ...compatibleProductsOptions,
          bundleComponent: `wallbox`,
        });
        extendedWarrantyCompatibilityRequest =
          featureFlags?.[`enable-extended-warranty`]?.status === `valid`
            ? fetchCartCompatibleProducts({
                ...compatibleCartProductRequestOptions,
                bundleComponent: `extended_warranty`,
              })
            : undefined;
        premiumConnectivityCompatibilityRequest =
          featureFlags?.[`enable-premium-connectivity`]?.status === `valid`
            ? fetchCartCompatibleProducts({
                ...compatibleCartProductRequestOptions,
                bundleComponent: `premium_connectivity`,
              })
            : undefined;
      } else {
        accessoriesCompatibleProductsRequest = fetchCompatibleProducts({
          ...compatibleProductsOptions,
          bundleComponent: `accessories`,
        });
        wallboxCompatibleProductsRequest = fetchCompatibleProducts({
          ...compatibleProductsOptions,
          bundleComponent: `wallbox`,
        });
        extendedWarrantyCompatibilityRequest =
          featureFlags?.[`enable-extended-warranty`]?.status === `valid`
            ? fetchCompatibleProducts({
                ...compatibleProductsOptions,
                bundleComponent: `extended_warranty`,
              })
            : undefined;
        premiumConnectivityCompatibilityRequest =
          featureFlags?.[`enable-premium-connectivity`]?.status === `valid`
            ? fetchCompatibleProducts({
                ...compatibleProductsOptions,
                bundleComponent: `premium_connectivity`,
              })
            : undefined;
      }
    } catch (e) {
      console.error(e);
    }
    // TODO: compatible products should probably be moved into own bffs to reduce loading time
    const results = await Promise.allSettled([
      fetchSmartModels({
        baseSiteId,
        endpoints,
        language,
      }),
      fetchLineOverview({
        baseSiteId,
        endpoints,
        language,
      }),
      accessoriesCompatibleProductsRequest,
      wallboxCompatibleProductsRequest,
      extendedWarrantyCompatibilityRequest,
      premiumConnectivityCompatibilityRequest,
    ]);

    const [
      allModelsResult,
      allLineOverviewResponseResult,
      accessoriesCompatibleProductsResult,
      wallboxCompatibleProductsResult,
      extendedWarrantyCompatibilityResultt,
      premiumConnectivityCompatibilityResult,
    ] = results;
    const allModels =
      allModelsResult.status === `fulfilled`
        ? allModelsResult.value
        : {data: []};
    const allLineOverviewResponse =
      allLineOverviewResponseResult.status === `fulfilled`
        ? allLineOverviewResponseResult.value
        : {data: []};
    const accessoryResponse =
      accessoriesCompatibleProductsResult.status === `fulfilled`
        ? accessoriesCompatibleProductsResult.value
        : undefined;
    const wallboxResponse =
      wallboxCompatibleProductsResult.status === `fulfilled`
        ? wallboxCompatibleProductsResult.value
        : undefined;
    const extendedWarrantyResponse =
      extendedWarrantyCompatibilityResultt?.status === `fulfilled`
        ? extendedWarrantyCompatibilityResultt.value
        : undefined;
    const premiumConnectivityResponse =
      premiumConnectivityCompatibilityResult?.status === `fulfilled`
        ? premiumConnectivityCompatibilityResult.value
        : undefined;

    const productCatalogueModel = createProductCatalogueModel(
      allModels.data,
      allLineOverviewResponse.data,
      accessoryResponse,
      extendedWarrantyResponse,
      wallboxResponse,
      premiumConnectivityResponse,
      {
        envName,
        preview,
      },
    );
    return {
      statusCode: 200,
      headers: {
        'Content-Type': `application/json`,
        // Please adopt to your business case. Highway to the danger zone!
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify(productCatalogueModel),
    };
  },
  {
    auth: false,
    fetchEndpoints: true,
    schema: {queryParams: queryParamsSchema},
    staticVerifySecret: JSON.stringify({
      headerName: `x-api-key`,
      headerValue: Config.ENDPOINT_DIRECTORY_API_KEY,
    }),
    logger,
    usedFeatureFlags: [
      `enable-extended-warranty`,
      `enable-premium-connectivity`,
    ],
  },
);

