import {useFeatureFlags} from '@smart/feature-app';
import {useQueryParams} from '@smart/react-utils';
import {Icon, Loader, Tabs} from '@smart/web-components';
import * as React from 'react';
import {useState} from 'react';
import {
  TabActive,
  type TabActiveEnum,
} from '../../../../types/tab-active.types';
import {UsedFeatureFlags} from '../../constants/common';
import {useAppModelContext} from '../../hooks/use-app-model';
import {useProductCatalogueModel} from '../../hooks/use-product-catalogue-model';
import {VehiclesTab} from '../vehicles-tab';
import {AccessoriesTab} from './accessories-tab';
import {ExtendedWarrantyTab} from './extended-warranty-tab';
import styles from './index.module.scss';
import {PremiumConnectivityTab} from './premium-connectivity-tab';
import {WallBoxTab} from './wallbox-tab';

const baseClass = `selector`;

export const CatalogueSelector = (): JSX.Element | null => {
  const {appModel} = useAppModelContext();
  const {
    vehiclesTabLabel,
    accessoriesTabLabel,
    wallboxesTabLabel,
    extendedWarrantyAemData: {tabName: extendedWarrantyTabLabel},
    premiumConnectivityAemData: {tabName: premiumConnectivityTabLabel},
  } = appModel;
  const {productCatalogueModel, error} = useProductCatalogueModel();
  const {queryParams, setQueryParams} = useQueryParams();

  // Initialize tabActive state based on the preselected tab from queryParams, defaulting to VEHICLES if none selected
  const tab: TabActiveEnum = queryParams.tab as TabActiveEnum;
  const [tabActive, setTabActive] = useState<TabActiveEnum>(
    tab ?? TabActive.VEHICLES,
  );

  // Update query parameters
  const updateActiveTabAndParams = (value: TabActiveEnum) => {
    setTabActive(value);
    setQueryParams(
      {tab: value.toLowerCase()},
      {replaceParams: true, stateful: false},
    );
  };

  const {enabled: isWallboxEnabled} = useFeatureFlags(
    UsedFeatureFlags.ENABLE_WALLBOX,
  );

  const {enabled: isExtendedWarrantyEnabled} = useFeatureFlags(
    UsedFeatureFlags.ENABLE_EXTENDED_WARRANTY,
  );

  const {enabled: isPremiumConnectivityEnabled} = useFeatureFlags(
    UsedFeatureFlags.ENABLE_PREMIUM_CONNECTIVITY,
  );

  if (error) {
    return <Icon name="error--medium" />;
  }

  if (!productCatalogueModel) {
    return <Loader size="medium" messageId="" />;
  }

  const vehicleTab = {
    headline: vehiclesTabLabel,
    id: `vehiclesTab`,
    content: (
      <VehiclesTab
        allLines={productCatalogueModel.allLines}
        models={productCatalogueModel.models}
        tabActive={tabActive}
      />
    ),
    onClick: () => updateActiveTabAndParams(TabActive.VEHICLES),
  };

  const accessoriesTab = {
    headline: accessoriesTabLabel,
    id: `accessoriesTab`,
    content: (
      <AccessoriesTab
        appModel={appModel}
        accessories={productCatalogueModel.accessories}
        models={productCatalogueModel.models}
        tabActive={tabActive}
      />
    ),
    onClick: () => updateActiveTabAndParams(TabActive.ACCESSORIES),
  };

  const showExtendedWarranty =
    isExtendedWarrantyEnabled && productCatalogueModel.extendedWarranty;

  const showPremiumConnectivity =
    isPremiumConnectivityEnabled && productCatalogueModel.premiumConnectivity;

  const extendedWarrantyTab = showExtendedWarranty && {
    headline: extendedWarrantyTabLabel,
    id: `extendedWarrantyTab`,
    content: (
      <ExtendedWarrantyTab
        appModel={appModel}
        extendedWarrantyOffers={productCatalogueModel.extendedWarranty}
        models={productCatalogueModel.models}
        tabActive={tabActive}
      />
    ),
    onClick: () => updateActiveTabAndParams(TabActive.EXTENDED_WARRANTY),
  };

  const premiumConnectivityTab = showPremiumConnectivity && {
    headline: premiumConnectivityTabLabel,
    id: `premiumConnectivityTab`,
    content: (
      <PremiumConnectivityTab
        appModel={appModel}
        premiumConnectivityOffers={productCatalogueModel.premiumConnectivity}
        models={productCatalogueModel.models}
        tabActive={tabActive}
      />
    ),
    onClick: () => updateActiveTabAndParams(TabActive.PREMIUM_CONNECTIVITY),
  };

  const showWallbox =
    isWallboxEnabled && productCatalogueModel.wallbox.length > 0;

  const wallBoxTab = showWallbox && {
    headline: wallboxesTabLabel,
    id: `wallboxesTab`,
    content: (
      <WallBoxTab
        appModel={appModel}
        wallBox={productCatalogueModel.wallbox}
        tabActive={tabActive}
        models={productCatalogueModel.models}
      />
    ),
    onClick: () => updateActiveTabAndParams(TabActive.WALLBOXES),
  };

  // construct a tuple of tabItems and a key used for query params
  const tabItemsTuples: {
    key: TabActiveEnum;
    value: typeof vehicleTab;
  }[] = [
    {key: TabActive.VEHICLES, value: vehicleTab},
    ...(wallBoxTab ? [{key: TabActive.WALLBOXES, value: wallBoxTab}] : []),
    {key: TabActive.ACCESSORIES, value: accessoriesTab},
    ...(extendedWarrantyTab
      ? [{key: TabActive.EXTENDED_WARRANTY, value: extendedWarrantyTab}]
      : []),
    ...(premiumConnectivityTab
      ? [{key: TabActive.PREMIUM_CONNECTIVITY, value: premiumConnectivityTab}]
      : []),
  ];

  // Get initial tab from query params if possible, else set initial tab to 0
  const handleInitialTab = () => {
    const tabValue = queryParams.tab;
    let tabIndex = 0;
    let tabValueStr: string | undefined;

    if (Array.isArray(tabValue) && tabValue.length >= 2 && tabValue[0]) {
      tabValueStr = tabValue[0];
    } else if (typeof tabValue === `string`) {
      tabValueStr = tabValue;
    }

    tabIndex = tabItemsTuples.findIndex(({key}) => key === tabValueStr);
    return tabIndex >= 0 ? tabIndex : 0;
  };

  // reconstruct tabItems
  const tabItems = tabItemsTuples.map(({value}) => value);

  return (
    <div className={styles[baseClass]}>
      <Tabs items={tabItems} initialTab={handleInitialTab()} />
    </div>
  );
};

