import {EventName, EventSource, EventType} from '@smart/analytics';
import {
  useFeatureAppEnv,
  useFeatureFlags,
  usePriceType,
} from '@smart/feature-app';
import {useTranslations} from '@smart/react-utils';
import type {MarketId} from '@smart/types';
import {MARKET, PAYMENT_TYPE} from '@smart/types';
import {getLabelsForMarketPriceTypePaymentType} from '@smart/utils';
import {Notification} from '@smart/web-components';
import * as React from 'react';
import type {PropsWithChildren} from 'react';
import {DIALOG} from '../../../../types/dialogs';
import {
  TabActive,
  type TabActiveEnum,
} from '../../../../types/tab-active.types';
import type {ProductSearchProduct} from '../../../bff/product-catalogue-model/create-product-catalogue-model';
import type {Model} from '../../../bff/types';
import {Templates} from '../../../types/utility';
import {UsedFeatureFlags} from '../../constants/common';
import {useAppModelContext} from '../../hooks/use-app-model';
import {useCart} from '../../hooks/use-cart-model';
import {useLocale} from '../../hooks/use-locale';
import {useTracking} from '../../hooks/use-tracking';
import {getDialogType} from '../../utils/get-dialog';
import {getTrackingEventData} from '../../utils/get-tracking-event-data';
import {truncPrice} from '../../utils/truncPrice';
import {AccessoriesDialog} from '../dialogs/accessories-dialog';
import {ExtendedWarrantyNotCompatibleDialog} from '../dialogs/extended-warranty-not-compatible-dialog';
import {IncompatibilityDialog} from '../dialogs/incompatibility-dialog';
import {MissingCarDialog} from '../dialogs/missing-car-dialog';
import {NotCashbuyDialog} from '../dialogs/not-cashbuy-dialog';
import {OutOfStockDialog} from '../dialogs/out-of-stock-dialog';
import {SelectVehicleDialog} from '../dialogs/select-vehicle-dialog';
import {SelectVehicleWallboxDialog} from '../dialogs/select-vehicle-wallbox-dialog';
import {EmptyState} from '../empty-state';
import {Tile} from '../tile';
import styles from './index.module.scss';

interface DialogContent {
  headline: string;
  text: string;
}

interface ContentTabProps {
  items: ProductSearchProduct[];
  disclaimerReference: string;
  exclVatLabel: string;
  inclVatLabel: string;
  tabActive: TabActiveEnum;
  models: Model[];
  cartEntryReplacedNotification?: DialogContent;
  isExtendedWarrantyTab?: boolean;
  isExtendedWarrantyDialogOpen?: boolean;
  setIsExtendedWarrantyDialogOpen?: React.Dispatch<
    React.SetStateAction<boolean>
  >;
  providerPath?: string;
}

export const ContentTab = ({
  items,
  disclaimerReference,
  cartEntryReplacedNotification,
  exclVatLabel,
  inclVatLabel,
  tabActive,
  models,
  providerPath,
  children,
}: PropsWithChildren<ContentTabProps>) => {
  const trackEvent = useTracking();

  const {cartModel, addEntryToCart, deleteEntryFromCart, replaceCart} =
    useCart();

  const {
    appModel: {
      estimatedDeliveryText,
      accessoriesAndWallboxes: {
        moreDetailsLinkLabel,
        moreDetailsLinkPath,
        priceLabel,
        addItemCtaLabel,
        itemAddedCtaLabel,
        soldByLabel,
        outOfStockModalHeadline,
        compatibleWithLabel,
      },
      inclVatLabelForAccessory,
      exclVatLabelForAccessory,
      deliveryFootnoteReference,
      translations,
    },
  } = useAppModelContext();
  const {marketId} = useLocale();

  const {t} = useTranslations(translations);

  const {
    featureServices: {'login-service': loginService, 'pub-sub': pubSubService},
  } = useFeatureAppEnv();
  const [priceType] = usePriceType();

  const [isUiBlocked, setIsUiBlocked] = React.useState(false);
  const [isWallBoxModalOpen, setIsWallBoxModalOpen] = React.useState(false);
  const [isAccessoriesModalOpen, setIsAccessoriesModalOpen] =
    React.useState(false);
  const [isNotCompatibleModalOpen, setIsNotCompatibleModalOpen] =
    React.useState(false);
  const [isOutOfStockModalOpen, setIsOutOfStockModalOpen] =
    React.useState(false);
  const [showNotification, setShowNotification] = React.useState(false);
  const [
    loggedInWithNoCarAndNoPurchaseNotification,
    setLoggedInWithNoCarAndNoPurchaseNotification,
  ] = React.useState(false);
  const [
    isExtendedWarrantyNotCashbuyDialogOpen,
    setIsExtendedWarrantyNotCashbuyDialogOpen,
  ] = React.useState(false);

  const [
    isExtendedWarrantyMissingCarDialogOpen,
    setIsExtendedWarrantyMissingCarDialogOpen,
  ] = React.useState(false);

  const [
    isExtendedWarrantyNotCompatibleDialogOpen,
    setIsExtendedWarrantyNotCompatibleDialogOpen,
  ] = React.useState(false);

  const {enabled: enableAnonymousFlow} = useFeatureFlags(
    UsedFeatureFlags.ENABLE_ANONYMOUS_FLOW,
  );

  const {enabled: enableMiniCart} = useFeatureFlags(
    UsedFeatureFlags.ENABLE_MINI_CART_MODAL,
  );

  React.useEffect(() => {
    if (showNotification) {
      const notificationTimer = setTimeout(() => {
        setShowNotification(false);
      }, 10000);

      return () => clearTimeout(notificationTimer);
    }

    return;
  }, [showNotification]);

  const itemsWithCartStatus = items.map((item) => {
    const itemInCart = cartModel?.products?.find(
      (productInCart) => item.productId === productInCart.code,
    );
    item.alreadyInCart = !!itemInCart;
    return item;
  });

  const soldProvidedByLabel =
    tabActive === TabActive.EXTENDED_WARRANTY &&
    marketId.toUpperCase() === MARKET.DE
      ? t(`providedBy`)
      : soldByLabel;

  const handleMoreInfoClick = (productCode: string, href: string) => {
    const product = items.find((item) => item.productId === productCode);
    if (!product) return;
    trackEvent(
      {
        name: EventName.MORE_INFO,
        type: EventSource.NAVIGATION,
        region: `catalogue`,
        url: window.location.href,
        destinationUrl: href,
        product: [
          {
            id: product.productId,
            name: product.headline,
            type: product.productType,
            priceUnit: truncPrice(product.priceRaw),
            priceTotal: truncPrice(product.priceRaw),
            inStock: product.stockLevelStatus,
            qty: 1,
            index: `${items.findIndex(
              (item) => product.productId === item.productId,
            )}`,
          },
        ],
      },
      EventType.CLICK,
    );
  };

  const handleAddItemClick = (
    productCode: string,
    incompatibleWithCart: boolean,
    isInStock: boolean,
    setLoading: (isLoading: boolean) => void,
    isWallbox?: boolean,
    wallboxEntryNumber?: number,
  ) => {
    const hasCar = cartModel?.totalItems;
    const hasPriorPurchase = cartModel?.hasVehicleOrder;
    const isCashBuy = cartModel?.paymentType === PAYMENT_TYPE.CASH;

    const dialog = getDialogType(
      tabActive,
      {
        loggedOut:
          !loginService.loginState ||
          loginService.loginState.status === `logged-out`,
        hasCar: Boolean(hasCar),
        hasPriorPurchase,
        incompatibleWithCart,
        outOfStock: !isInStock,
        isCashBuy,
      },
      {
        enableAnonymousFlow,
      },
    );

    if (dialog === DIALOG.ACCESSORIES) {
      if (enableMiniCart) {
        pubSubService.publish(`add-to-mini-cart`, {
          accessoriesMissingForVehicle: true,
        });
      } else {
        setIsAccessoriesModalOpen(true);
      }

      return;
    }
    if (dialog === DIALOG.ACCESSORIES_NOT_COMPATIBLE) {
      if (enableMiniCart) {
        pubSubService.publish(`add-to-mini-cart`, {
          accessoriesNotCompatible: true,
          accessoriesCode: productCode.split(`_`)[0],
        });
      } else {
        setIsNotCompatibleModalOpen(true);
      }

      return;
    }
    if (dialog === DIALOG.ACCESSORIES_OUT_OF_STOCK) {
      setIsOutOfStockModalOpen(true);
      return;
    }
    if (dialog === DIALOG.WALLBOX) {
      setIsWallBoxModalOpen(true);
      return;
    }
    if (dialog === DIALOG.WALLBOX_NO_PURCHASE) {
      setLoggedInWithNoCarAndNoPurchaseNotification(true);
      return;
    }

    if (dialog === DIALOG.EXT_WARRANTY_NOT_CASHBUY) {
      setIsExtendedWarrantyNotCashbuyDialogOpen(true);
      return;
    }
    if (dialog === DIALOG.EXT_WARRANTY_MISSING_CAR) {
      if (enableMiniCart) {
        pubSubService.publish(`add-to-mini-cart`, {
          extendedWarrantyMissingForVehicle: true,
        });
      } else {
        setIsExtendedWarrantyMissingCarDialogOpen(true);
      }
      return;
    }
    if (dialog === DIALOG.EXT_WARRANTY_NOT_COMPATIBLE) {
      if (enableMiniCart) {
        pubSubService.publish(`add-to-mini-cart`, {
          extendedWarrantyNotCompatible: true,
        });
      } else {
        setIsExtendedWarrantyNotCompatibleDialogOpen(true);
      }

      return;
    }

    const addedProduct = items.find((item) => item.productId === productCode);

    const addTrackingEventData = getTrackingEventData({
      name: `add_to_cart`,
      product: addedProduct && {
        type: addedProduct.productType,
        id: addedProduct.productId,
        name: addedProduct.headline,
        priceUnit: truncPrice(addedProduct.priceRaw),
        priceTotal: truncPrice(addedProduct.priceRaw),
        inStock: addedProduct.stockLevelStatus,
        qty: 1,
        index: `${items.findIndex(
          (item) => addedProduct.productId === item.productId,
        )}`,
      },
    });

    if (wallboxEntryNumber !== undefined) {
      const replacedProductCode = cartModel?.products?.find(
        (model) => model.entryNumber === wallboxEntryNumber,
      )?.code;
      const replacedProduct = items.find(
        (item) => item.productId === replacedProductCode,
      );

      const removeTrackingEventData = getTrackingEventData({
        name: `remove_from_cart`,
        product: replacedProduct && {
          type: replacedProduct.productType,
          id: replacedProduct.productId,
          name: replacedProduct.headline,
          priceUnit: truncPrice(replacedProduct.priceRaw),
          priceTotal: truncPrice(replacedProduct.priceRaw),
          inStock: replacedProduct.stockLevelStatus,
          qty: 1,
          index: `${items.findIndex(
            (item) => replacedProduct.productId === item.productId,
          )}`,
        },
      });

      replaceCart(
        wallboxEntryNumber,
        productCode,
        setLoading,
        () => trackEvent(removeTrackingEventData, EventType.CLICK),
        () => trackEvent(addTrackingEventData, EventType.CLICK),
      );
      return;
    }

    addEntryToCart(
      productCode,
      setLoading,
      () => trackEvent(addTrackingEventData, EventType.CLICK),
      isWallbox,
    );
  };

  const handleAddWallboxEntry = (
    productCode: string,
    incompatibleWithCart: boolean,
    isInStock: boolean,
    setLoading: (isLoading: boolean) => void,
  ) => {
    const handleLoadingState = (isLoading: boolean) => {
      setLoading(isLoading);
      setIsUiBlocked(isLoading);
    };

    if (cartModel?.wallboxEntryNumber !== undefined) {
      // Replace the existing wallbox in the cart
      handleAddItemClick(
        productCode,
        incompatibleWithCart,
        isInStock,
        (loadingState: boolean) => {
          handleLoadingState(loadingState);

          // TODO: Refactor - Notification is shown if the fetch fails as well
          if (!loadingState) {
            setShowNotification(true);
          }
        },
        true,
        cartModel.wallboxEntryNumber,
      );

      return;
    }

    handleAddItemClick(
      productCode,
      incompatibleWithCart,
      isInStock,
      handleLoadingState,
      true,
    );
  };

  const handleDeleteEntryHandler = (
    cartEntryNumber: number,
    setLoading: (isLoading: boolean) => void,
  ) => {
    const deletedProductCode = cartModel?.products?.find(
      (model) => model.entryNumber === cartEntryNumber,
    )?.code;
    const product = items.find((item) => item.productId === deletedProductCode);

    const trackingEventData = getTrackingEventData({
      name: `remove_from_cart`,
      product: product && {
        type: product.productType,
        id: product.productId,
        name: product.headline,
        priceUnit: truncPrice(product.priceRaw),
        priceTotal: truncPrice(product.priceRaw),
        inStock: product.stockLevelStatus,
        qty: 1,
        index: `${items.findIndex(
          (item) => product.productId === item.productId,
        )}`,
      },
    });

    deleteEntryFromCart(cartEntryNumber, setLoading, () =>
      trackEvent(trackingEventData, EventType.CLICK),
    );
  };

  const isAccessory = tabActive === TabActive.ACCESSORIES;

  const fallbackLabel =
    priceType === `commercial` ? exclVatLabel : inclVatLabel;

  const {vatLabel = fallbackLabel, accessoryVatLabel = fallbackLabel} =
    getLabelsForMarketPriceTypePaymentType({
      marketId: marketId as MarketId,
      labels: isAccessory
        ? {
            accessoryExclVatLabel: exclVatLabelForAccessory || exclVatLabel,
            accessoryInclVatLabel: inclVatLabelForAccessory || inclVatLabel,
          }
        : {
            excludeVatLabel: exclVatLabel,
            includesVatLabel: inclVatLabel,
          },
      paymentType: PAYMENT_TYPE.CASH,
      priceType,
    });

  return (
    <div className={styles.wrapper}>
      {children}
      {itemsWithCartStatus.length > 0 ? (
        <div className={styles.tilesContainer}>
          {itemsWithCartStatus.map((item: ProductSearchProduct) => {
            const estimatedDelivery =
              item?.earliestBeautifiedLeadTime &&
              estimatedDeliveryText.replace(
                Templates.days,
                item.earliestBeautifiedLeadTime,
              );

            const priceForPriceTypeConfig = {
              commercial: item.netPrice,
              private: item.price,
            };

            const price = priceForPriceTypeConfig[priceType];
            const deliveryInfo = () => {
              if (tabActive !== TabActive.VEHICLES) {
                return item.isInStock ? t(`inStock`) : outOfStockModalHeadline;
              }

              return item.isInStock
                ? estimatedDelivery
                : outOfStockModalHeadline;
            };
            return (
              <Tile
                outOfStockHeadline={outOfStockModalHeadline}
                imageUrl={item.imageUrl}
                heading={item.headline}
                description={item.description}
                moreDetailsLabel={moreDetailsLinkLabel}
                moreDetailsHref={moreDetailsLinkPath}
                priceLabel={
                  tabActive === TabActive.PREMIUM_CONNECTIVITY
                    ? `Price for 12 Months(No Auto-Renewal)`
                    : priceLabel
                }
                priceDisclaimerReference={disclaimerReference}
                price={price}
                alreadyInCart={item.alreadyInCart}
                addItemLabel={addItemCtaLabel}
                addedItemLabel={itemAddedCtaLabel}
                soldByTitleLabel={soldProvidedByLabel}
                soldByTitleValue={item.soldBy}
                providerPath={providerPath}
                handleAddItemClick={
                  tabActive === TabActive.WALLBOXES
                    ? handleAddWallboxEntry
                    : handleAddItemClick
                }
                handleDeleteEntryHandler={handleDeleteEntryHandler}
                handleMoreInfoClick={handleMoreInfoClick}
                key={item.productId}
                vatLabel={isAccessory ? accessoryVatLabel : vatLabel}
                productCode={item.productId}
                incompatibleWithCart={item.incompatibleWithCart}
                isInStock={item.isInStock}
                cartEntryNumber={
                  (cartModel?.products || []).find(
                    (cartProduct) => cartProduct.code === item.productId,
                  )?.entryNumber
                }
                // TODO: Improve "in stock" logic for accessories & extended warranty when we know how the API response will be
                deliveryInfo={deliveryInfo()}
                deliveryFootnoteReference={deliveryFootnoteReference}
                disabled={isUiBlocked}
                compatibleWithLabel={compatibleWithLabel}
                models={models ?? []}
                compatibleLines={item.compatibleLines}
                isWallboxTab={tabActive === TabActive.WALLBOXES}
                isExtendedWarrantyTab={
                  tabActive === TabActive.EXTENDED_WARRANTY
                }
                badges={item.badges}
              />
            );
          })}
        </div>
      ) : (
        <EmptyState />
      )}
      {isExtendedWarrantyNotCompatibleDialogOpen && (
        <ExtendedWarrantyNotCompatibleDialog
          onOpenChange={setIsExtendedWarrantyNotCompatibleDialogOpen}
          open={isExtendedWarrantyNotCompatibleDialogOpen}
        />
      )}

      {isExtendedWarrantyNotCashbuyDialogOpen && (
        <NotCashbuyDialog
          onOpenChange={setIsExtendedWarrantyNotCashbuyDialogOpen}
          open={isExtendedWarrantyNotCashbuyDialogOpen}
        />
      )}
      {isExtendedWarrantyMissingCarDialogOpen && (
        <MissingCarDialog
          onOpenChange={setIsExtendedWarrantyMissingCarDialogOpen}
          open={isExtendedWarrantyMissingCarDialogOpen}
        />
      )}

      {isAccessoriesModalOpen && (
        <AccessoriesDialog
          onOpenChange={setIsAccessoriesModalOpen}
          open={isAccessoriesModalOpen}
        />
      )}

      {isNotCompatibleModalOpen && (
        <IncompatibilityDialog
          onOpenChange={setIsNotCompatibleModalOpen}
          open={isNotCompatibleModalOpen}
        />
      )}

      {isWallBoxModalOpen && (
        <SelectVehicleWallboxDialog
          onOpenChange={setIsWallBoxModalOpen}
          open={isWallBoxModalOpen}
        />
      )}

      {loggedInWithNoCarAndNoPurchaseNotification && (
        <SelectVehicleDialog
          onOpenChange={setLoggedInWithNoCarAndNoPurchaseNotification}
          open={loggedInWithNoCarAndNoPurchaseNotification}
        />
      )}

      {isOutOfStockModalOpen && (
        <OutOfStockDialog
          onOpenChange={setIsOutOfStockModalOpen}
          open={isOutOfStockModalOpen}
        />
      )}

      {showNotification && cartEntryReplacedNotification && (
        <Notification
          className={styles.cartNotification}
          variant="informational"
          label={cartEntryReplacedNotification.headline}
          text={cartEntryReplacedNotification.text}
          closeButton={{
            ariaLabel: `Close`,
            onClick: () => setShowNotification(false),
          }}
        />
      )}
    </div>
  );
};

