import {BuildTimestampPlugin} from '@smart/server-utils';
import MiniCssExtractPlugin from 'mini-css-extract-plugin';
import type {Configuration} from 'webpack';
import webpack from 'webpack';
import merge from 'webpack-merge';
import {buildPath, getCommonConfig} from './webpack.config.common';

interface FeatureAppOptions {
  readonly mode: Configuration['mode'];
  readonly baseUrl: string;
  readonly target: string;
  readonly stage: string;
  readonly featureAppName: string;
  readonly hostedZone: string;
}

export const getFeatureAppConfig = (
  options: FeatureAppOptions,
): Configuration => {
  const config: Configuration = {
    mode: options.mode,
    entry: {}, // intentionally left empty, defined by ModuleFederationPlugin
    output: {
      filename: `feature-app.js`,
      path: buildPath(`build`, `assets`, `feature-app`),
      publicPath: `${options.baseUrl}/assets/feature-app/`,
      chunkFilename: `feature-app.[name].[contenthash].js`,
    },
    plugins: [
      ...(options.mode === `development`
        ? [
            new webpack.SourceMapDevToolPlugin({
              filename: `[file].map`,
              namespace: `${options.featureAppName}/${options.target}`,
            }),
          ]
        : []),
      new MiniCssExtractPlugin({
        filename: `feature-app.css`,
        chunkFilename: `feature-app.[name].[contenthash].css`,
      }),
      new webpack.container.ModuleFederationPlugin({
        name: `__feature_hub_feature_app_module_container__`,
        exposes: {featureAppModule: `./src/feature-app/feature-app.tsx`}, // Webpack entry
        shared: {
          'react': {singleton: true},
          'react-dom': {singleton: true},
          'markdown-to-jsx': {},
          '@feature-hub/react': {singleton: true},
        },
      }),
      new BuildTimestampPlugin({target: options.target}),
    ],
    resolve: {
      fallback: {
        child_process: false,
      },
    },
  };

  return merge(getCommonConfig(options), config);
};
